//! `ghost`: the ghost monsters (small / medium / big ghosts and the Ep6 ghost boss). One shared C
//! source (`Monster_Base.c`, `Ghost_base.c`, `Glow.c`, `GhostGlowInit.c`) compiled with a per-level
//! file (`<Size>GhostLevel<N>.c` + `<Size>GhostEpisode<N>.c`) into one module per level pack.
//! Port of `Game Logic Modules/<Episode>/Characters/{SMALL_GHOST,MEDIUM_GHOST,Big_Ghost,GHOST_BOSS}/..`.
//! Reference build: smallghostlevelone__757255de (EP1L01). The 31 builds are listed in
//! `tools/rustport/ghost_family.txt`; per-build literals and code shapes are in [`builds`]
//! (generated by tools/rustport/gen_builds.py), the initialised tables in [`maps`].
//!
//! This is the monster side of the Tome of Doom: a ghost flees while the book is open
//! (`TomeIsOpen` -> `Ghost_BaseTR_TOME_IS_OPEN_SET` -> `Ghost_BaseST_TOME_IS_OPEN_FLEE`), gets hooked by
//! the book's beam (message 0xd6/0x65 from the book -> `Ghost_BaseTR_HOOKED_BY_BOOK_SET` ->
//! `Ghost_BaseST_BEINGSUCKED_LOOP`), is pulled in (0xd6/0x67) and captured (0xd6/0x68 ->
//! `Monster_BaseST_CAPTURED`), and comes back on 0xc9/0xc1 when released.
//!
//! PORT STATUS: the shared code is ported for every build. Level files: see [`level`].
//!
//! Module globals are shared by every instance (the engine swaps `pLocalData*` per instance), as on
//! the PS2. `pLocalDataMonster_Base` and `pLocalDataGhost_Base` both point at the instance's one
//! local data block (GetLocalData grows and shares it), likewise the two global data pointers.
#![allow(non_snake_case, non_upper_case_globals, unused_variables, unused_mut, unused_assignments)]
#![allow(clippy::all)]

pub mod builds;
pub mod maps;

pub mod emitter_pos;
mod ghost_base;
mod ghost_glow_init;
mod glow;
mod level;
mod monster_base;

pub use ghost_base::*;
pub use ghost_glow_init::*;
pub use glow::*;
pub use level::*;
pub use monster_base::*;

use crate::engine::{Engine, Mem, Ptr};
use crate::logic::{LResult, ModuleDef};

pub static MODULE: ModuleDef = ModuleDef {
    name: "ghost",
    data_size: DATA_SIZE,
    ctor: ghost_levelConstructor,
    dtor: ghost_levelDestructor,
    register: None,
    // the initialised data the code reads (goCustomDataGhost, TmpMonsterMap) is written per build by
    // ghost_build_init; string literals are interned with `e.cstr`.
    init: &[],
    build_init: Some(ghost_build_init),
};

/// Index of a build in [`builds::BUILDS`] by its SHA-1 prefix (or directory name for the builds whose
/// directory has no `__<sha8>` suffix, e.g. `bigghostlevelfour`).
pub fn build_index(sha8: &str) -> Option<usize> {
    builds::BUILDS.iter().position(|b| b.sha8 == sha8)
}

fn ghost_build_init(m: &mut Mem, data: Ptr, build: usize) {
    for (i, &w) in maps::GO_CUSTOM_DATA_GHOST[build].iter().enumerate() {
        m.w32(data + (goCustomDataGhost - 0x10000) + i as u32 * 4, w);
    }
    for (i, &w) in maps::TMP_MONSTER_MAP[build].iter().enumerate() {
        m.w32(data + (TmpMonsterMap - 0x10000) + i as u32 * 4, w);
    }
}

// ---- module globals ----
// The builds place their globals at different addresses (the two tables have per-level sizes); the
// image is private to the module, so the port uses one layout for every build: the tables at their
// largest size, then the pointers in _globals.h order.
/// per-ghost-object data: records {object id, path A, path B, kill mask, sector mask} of 0x14 bytes
/// (0x18 in 4 builds); 200 bytes max
pub const goCustomDataGhost: u32 = 0x10000;
/// per-monster-type data: records of 0x3c bytes {type, speeds and ranges...}; 300 bytes max
pub const TmpMonsterMap: u32 = 0x100c8;
pub const pAnimMngr: u32 = 0x10200;
pub const pFunction: u32 = 0x10204;
pub const pMiscFunc: u32 = 0x10208;
pub const pDebug: u32 = 0x1020c;
pub const pExtra: u32 = 0x10210;
pub const pGameObj: u32 = 0x10214;
pub const pPhysic: u32 = 0x10218;
pub const pParticle: u32 = 0x1021c;
pub const pMath: u32 = 0x10220;
pub const pStdlib: u32 = 0x10224;
pub const pLight: u32 = 0x10228;
pub const pAnim: u32 = 0x1022c;
pub const pSound: u32 = 0x10230;
pub const pGraphic: u32 = 0x10234;
pub const pSectorClip: u32 = 0x10238;
/// `LIBApiText *` (3 builds' level files)
pub const pText: u32 = 0x1023c;
pub const pLocalDataMonster_Base: u32 = 0x10240;
pub const pGlobalDataMonster_Base: u32 = 0x10244;
pub const pLocalDataGhost_Base: u32 = 0x10248;
pub const pGlobalDataGhost_Base: u32 = 0x1024c;
pub const DATA_SIZE: u32 = 0x300;

/// `ALL` joint / bone selector (0x7fffffff)
pub(crate) const ALL: u32 = 0x7fff_ffff;

/// Address of a module global.
#[inline]
pub(crate) fn G(e: &Engine, a: u32) -> Ptr {
    e.rt.cur_data() + (a - 0x10000)
}
/// Current value of `pLocalDataGhost_Base` (this instance's local data).
#[inline]
pub(crate) fn L(e: &Engine) -> Ptr {
    e.r32(G(e, pLocalDataGhost_Base))
}
/// Current value of `pLocalDataMonster_Base` (the same block as [`L`] once both are registered).
#[inline]
pub(crate) fn LM(e: &Engine) -> Ptr {
    e.r32(G(e, pLocalDataMonster_Base))
}
/// Current value of `pGlobalDataMonster_Base` (byte-addressed: [0] game buffer 0, [1] game buffer 2,
/// [2] game buffer 1, [3] the APIcons table, set by ghost_baseConstructor).
#[inline]
pub(crate) fn GDM(e: &Engine) -> Ptr {
    e.r32(G(e, pGlobalDataMonster_Base))
}
/// Current value of `pGlobalDataGhost_Base` (the same block as [`GDM`]).
#[inline]
pub(crate) fn GDG(e: &Engine) -> Ptr {
    e.r32(G(e, pGlobalDataGhost_Base))
}
/// Per-build literal (see builds.rs).
#[inline]
pub(crate) fn k(e: &Engine, i: usize) -> u32 {
    builds::BUILDS[e.rt.cur_build()].k[i]
}
/// Per-build code shape group of a function (see builds.rs).
#[inline]
pub(crate) fn g(e: &Engine, i: usize) -> u8 {
    builds::BUILDS[e.rt.cur_build()].g[i]
}
/// The current build's directory/sha8 key.
#[inline]
pub(crate) fn build_key(e: &Engine) -> &'static str {
    builds::BUILDS[e.rt.cur_build()].sha8
}

/// `pcVar = (*((APIcons *)pGlobalDataGhost_Base[3])->GetExternalFunction)(idx); (*pcVar)(0);`
/// Runs the module function registered under `idx` at once, inside the current logic call (no
/// setjmp of its own: a ChangeState/Break in it unwinds the caller as well, as on the PS2). A NULL
/// entry is a call through NULL in the original: panic.
pub(crate) fn call_external_now(e: &mut Engine, idx: u32) -> LResult<()> {
    let c = e.rt.current_code().expect("GetExternalFunction outside of a logic call");
    let f = e
        .GetFunction(c, idx)
        .unwrap_or_else(|| panic!("ghost: call through NULL (external function {idx:#x} not set)"));
    f(e, 0)?;
    Ok(())
}

/// `L + off |= bits` (the event flags at L+0x19c and similar read-modify-writes).
#[inline]
pub(crate) fn or32(e: &mut Engine, a: Ptr, bits: u32) {
    let v = e.r32(a);
    e.w32(a, v | bits);
}
